<template>
    <div class="layout-px-spacing">  
            <ul class="navbar-nav flex-row mt-2">
                <li>
                    <div class="page-header">
                        <nav class="breadcrumb-one" aria-label="breadcrumb">
                            <ol class="breadcrumb">
                                <li class="breadcrumb-item"><a href="javascript:;">Masters</a></li>
                                <li class="breadcrumb-item active" aria-current="page"><span>Users</span></li>
                            </ol>
                        </nav>
                    </div>
                </li>
            </ul>
            <div class="d-flex me-4 mt-2 ">
                        <div class="ms-auto">
                            <button class="btn btn-primary " @click="item_registration =! item_registration;">                           
                                <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" fill="currentColor" class="bi bi-plus-square" viewBox="0 0 16 16">
  <path d="M14 1a1 1 0 0 1 1 1v12a1 1 0 0 1-1 1H2a1 1 0 0 1-1-1V2a1 1 0 0 1 1-1zM2 0a2 2 0 0 0-2 2v12a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V2a2 2 0 0 0-2-2z"/>
  <path d="M8 4a.5.5 0 0 1 .5.5v3h3a.5.5 0 0 1 0 1h-3v3a.5.5 0 0 1-1 0v-3h-3a.5.5 0 0 1 0-1h3v-3A.5.5 0 0 1 8 4"/>
</svg>
</button>
 
                        </div>
                    </div>  
                    
         
       
 <!-- item registration form starts -->
 <form v-if="item_registration" class="mt-3 p-3 border rounded bg-white shadow" @submit.prevent="registerUser()">
        <h4 class="text-center">USER REGISTRATION FORM</h4>
        <div class="row mb-2">
    
            <div class="col-md-4">
                <label class="form-label">User Name</label>
                <input type="text" class="form-control" placeholder="Enter User Name" v-model="username" required>
            </div>

            <div class="col-md-4">
                <label class="form-label" >User Role</label>
    <multiselect 
                v-model="user_role"
                :options= "roles"
                placeholder="select role"
                label="name"
                :searchable = "true"        
                multple="false"
                :required="true"
                :allow-empty="false"
            ></multiselect>
            </div>
            <div class="col-md-4">
                <label class="form-label">Password</label>
                <input type="password" class="form-control" placeholder="Enter Password" v-model="password" step="any" required>
            </div>
            <div class="col-md-4">
                <label class="form-label">Phone Number</label>
                <input type="text" class="form-control" placeholder="Enter Phone Number" v-model="phone_no" step="any" required>
            </div>
            <div class="col-md-4">
                <label class="form-label">Location</label>
                <multiselect 
                    v-model="location"
                    :options="locations"
                    placeholder="Select Location"
                    label="name"
                    :searchable="true"        
                    :multiple="false"
                    :required="true"
                    :allow-empty="false"
                ></multiselect>
            </div>
            <div class="col-md-4">
                <label class="form-label">Email</label>
                <input type="email" class="form-control" placeholder="Enter Email" v-model="useremail" step="any" required>
            </div>
        </div>
        <div class="text-center gap-2 justify-content-end">
            <button type="button" class="btn btn-danger me-3" @click="item_registration = false; closeEditModal()">Cancel</button>
            <button type="submit" class="btn btn-primary" :disabled="registeringUser">
                <span v-if="registeringUser" class="spinner-border spinner-border-sm me-1" role="status" aria-hidden="true"></span>
                <span v-else>Register</span>
            </button>
        </div>
    </form>
             <!-- item registration form ends-->
    


        <div class="row layout-top-spacing">
            <div class="col-xl-12 col-lg-12 col-sm-12 layout-spacing">
                <div class="panel p-0">
                    <div class="custom-table table3">
                        <div v-if="loading_spinner" v-html="tableShimmer()"></div>
                        <v-client-table v-else :data="items" :columns="columns" :options="table_option" >
                            <template #status="props">
                                <span class="badge inv-status" :class="'badge-' + props.row.status.class">{{ props.row.status.key }} </span>
                            </template>
                            <template #actions="props">

  <a  href="javascript:void(0)" class="text-success" title="Edit" 
     @click="openEditModal(props.row)" data-bs-toggle="modal" 
     :data-bs-target="'#edit-user-modal'">
   <svg
                                        xmlns="http://www.w3.org/2000/svg"
                                        width="24"
                                        height="24"
                                        viewBox="0 0 24 24"
                                        fill="none"
                                        stroke="currentColor"
                                        stroke-width="1.5"
                                        stroke-linecap="round"
                                        stroke-linejoin="round"
                                        class="text-primary"
                                    >
                                        <path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"></path>
                                        <path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"></path>
                                    </svg>
  </a>

</template>
                        </v-client-table>
                    </div>
                </div>
            </div>
        </div>

        <!-- user editing modal starts -->
<div class="modal fade mymodal" id="edit-user-modal" data-bs-backdrop="false" data-bs-keyboard="false" tabindex="-1" aria-labelledby="editUserModalLabel" aria-hidden="true">
  <div class="modal-dialog modal-xl">
    <div class="modal-content">
      <div class="modal-header">
        <h1 class="modal-title fs-5" id="editUserModalLabel">Edit User</h1>
        <button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close" id="close_editing" @click="closeEditModal()"></button>
      </div>
   <form @submit.prevent="updateUser(selectedId)">
  <div class="modal-body">
    <div class="row">
      <div class="col-md-4">
        <label class="form-label">User Name</label>
        <input type="text" class="form-control" v-model="username" >
      </div>
        <div class="col-md-4">
        <label class="form-label">User Role</label>
        <Multiselect
          v-model="user_role"
          :options="roles"
          :close-on-select="true"
          label="name"
          value-prop="id"
          placeholder="Select a role"
          :searchable="true"
        />
      </div>
      <div class="col-md-4">
        <label class="form-label">Phone Number</label>
        <input type="text" class="form-control bg-white" v-model="phone_no">
      </div>
      <div class="col-md-4">
                <label class="form-label">Location</label>
                <multiselect 
                    v-model="location"
                    :options="locations"
                    placeholder="Select Location"
                    label="name"
                    :searchable="true"        
                    :multiple="false"
                    :required="true"
                    :allow-empty="false"
                ></multiselect>
            </div>
              <div class="col-md-4">
        <label class="form-label">Email</label>
        <input type="text" class="form-control bg-white" v-model="useremail">
      </div>

     <div class="col-md-4">
    <label class="form-label">User Directory</label>
    <multiselect 
        v-model="directory_user"
        :options="userDirectory"
        placeholder="Select User"
        label="name"
        track-by="uu_id"
        :searchable="true"        
        :multiple="false"
        :allow-empty="true"
        @select="onDirectorySelect"
        @remove="uuid = ''"
    ></multiselect>
</div>
      
      <div class="col-md-6">
        <label class="form-check-label">
          <input type="checkbox" v-model="updatePassword" class="form-check-input"> Update Password
        </label>
      </div>

      <div class="col-md-6" v-if="updatePassword">
        <label class="form-label">New Password</label>
        <input type="password" v-model="password" class="form-control">
      </div>
    </div>
  </div>
  <div class="modal-footer">
    <button type="button" class="btn btn-danger" data-bs-dismiss="modal" id="close_editing">Close</button>
    <button type="submit" class="btn btn-secondary" :disabled="loading">
      <span v-if="loading" class="spinner-border spinner-border-sm text-white me-2" role="status"></span>
      <span v-else>Save changes</span>
    </button>
  </div>
</form>

      </div>
    </div>
  </div>
        <!-- user editing modal ends -->

  
    </div>
</template>

<script setup>
    import { onMounted, ref,inject } from 'vue';
    import axios from 'axios';
    import { useMeta } from '@/composables/use-meta';
    useMeta({ title: 'Custom Table' });
     import Multiselect from '@suadelabs/vue3-multiselect';
    import '@suadelabs/vue3-multiselect/dist/vue3-multiselect.css';
    
    const updatePassword = ref(false);
    const showMessage = inject('showMessage');
    const showError = inject('showError');
    const tableShimmer = inject('tableShimmer');
    const name = ref('');
    const loading_spinner = ref(false);
    const username = ref('');
    const uuid = ref('');
    const useremail = ref('');
    const phone_no = ref('');
    const password = ref('');
    const user_role = ref('');
    const selectedId = ref('');
    const phone = ref('');
    const roles = ref([]);
    const columns = ref(['Sn','User_ID','Username','role','Email','phone_no','location','actions']);
    const items = ref([
        
    ]);
    const item_registration = ref(false);
    const table_option = ref({
        perPage: 20,
        perPageValues: [ 20, 50,  100 ],
        skin: 'table table-hover table-striped',
        columnsClasses: { actions: 'actions text-center' },
        sortable: ['Sn','User ID' ],
        sortIcon: {
            base: 'sort-icon-none',
            up: 'sort-icon-asc',
            down: 'sort-icon-desc',
        },
        pagination: { nav: 'scroll', chunk: 5 },
        texts: {
            count: 'Showing {from} to {to} of {count}',
            filter: '',
            filterPlaceholder: 'Search...',
            limit: 'Results:',
        },
        resizableColumns: false,
    });

    const axiosInstance = axios.create({
        baseURL: process.env.VUE_APP_API_BASE_URL
    });


    const getRoles = () => {
        loading_spinner.value = true;
         axiosInstance.get('/roles').
         then((response) => {
            roles.value= response.data;
            loading_spinner.value = false;
        });
    };


    const getUsers = async (showSpinner = true) => {
        if (showSpinner) {  
            loading_spinner.value = true;
        }
      
        try {
            const response = await axiosInstance.get('/users');
            items.value = response.data.map((item, index) => ({
                ...item,
                Sn: index + 1,
                role_id: item.role,
                User_ID: item.id,
                location: item.location.name,
                location_id: item.location.id,
                Username: item.name,
                Email: item.email,
                phone_no: item.phone_no || '--',
                role:item.role_name
            }));
        } catch (error) {
            showError(error.message);
            console.error("Error fetching users:", error);
        } finally {
            if (showSpinner) {  
                loading_spinner.value = false;
            }
        }
    };

const registeringUser = ref(false);
    const registerUser = async () => {
       
        if (!username.value || !useremail.value) {
            showError("Please!..Provide username and email.");
            return;
        }

        if (!password.value) {
            showError("User must have password...");
            return;
        }
        
        registeringUser.value = true;
        
        const itemData = {
            name: username.value,
            email: useremail.value,
            role: user_role.value.id, 
            password: password.value,
            phone_no: phone_no.value,
            location_id: location.value.id,
        };
        
        try {
            const response = await axiosInstance.post('/users', itemData);
            await getUsers(false);
            showMessage('User registered successfully!');
            item_registration.value = false;           
        } catch (error) {
            console.error("Error registering User:", error);
            showError(error.message);
        } finally {
            registeringUser.value = false;
        }
    };


    const directory_user = ref(null);

const onDirectorySelect = (option) => {
    uuid.value = option.uu_id;
    username.value = option.name;
};


    const loading = ref(false);

    const updateUser = async (id) => {
        loading.value = true; 
        const newItemData = {
            role: user_role.value.id, 
            name: directory_user.value?.name,
            location_id: location.value.id,
            email: useremail.value,
            uuid:uuid.value,
            phone_no: phone_no.value,
            ...(password.value && { password: password.value }),
        };

        try {
            const response = await axiosInstance.put(`/users/${id}`, newItemData);
            getUsers(false);
            document.getElementById('close_editing').click();
            showMessage('User updated successfully!');
        } catch (error) {
            showError(error.message);
            console.log(error);
        } finally {
            loading.value = false; 
        }
    };

       const openEditModal = (row) => {
        user_role.value = roles.value.find(r => r.id == row.role_id); 
        password.value = '';
        username.value = row.name;
        uuid.value = row.uuid;
directory_user.value = userDirectory.value.find(u => u.uu_id === row.uuid) || null;
        useremail.value = row.email;
        phone_no.value = row.phone_no;
        location.value = locations.value.find(l => l.id == row.location_id); 
        selectedId.value = row.id;
        updatePassword.value = false;
    };

       const closeEditModal = () => {
        user_role.value='',
        password.value='',
        username.value='',
        useremail.value='',
        phone_no.value='',
        phone_no.value='',
        location.value='',
        directory_user.value = null;
uuid.value = '';
    };

    const location = ref('');
    const locations = ref([]);
    const getLocations = async () => {
        try {
            const response = await axiosInstance.get('/locations');
            locations.value = response.data;
        } catch (error) {
            console.error(error);
            showError(error.message);
        } finally {
            loading_spinner.value = false;
        }
    };



const userDirectory = ref([])
const getUserDirectory = async () => {
    const response = await axiosInstance.get(`user-directory/users?service_id=19`);

    userDirectory.value = response.data.data.users.map((item) => ({
        uu_id: item.uuid,
        name: item.username,
        phone: item.phone_number,
        email: item.email
    }));
};





    onMounted(() => {
        getUsers();
        getUserDirectory();
        getRoles();
        getLocations();
    });
</script>
